pieces = ["TEST", "EDGE", "CASES", "FIRST"]

def make_flag(items):
    body = ""
    for i in range(1, len(items)):
        body = body + items[i]
        if i < len(items) - 1:
            body = body + "_"
    return "FLAG{" + body + "}"

print(make_flag(pieces))

